def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"
        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        value = re.split(r"x|ext|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = "".join(ch for ch in value if ch.isdigit())
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        return digits

    def valid_phone(value):
        return len(value) == 10 and value[0] not in "01"

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        email = email if valid_email(email) else ""

        phone = normalize_phone(row["phone"])
        phone = phone if valid_phone(phone) else ""

        if not email and not phone:
            continue

        updated = parse_updated(row["updated"])
        first_name = normalize_name(row["first_name"])
        last_name = normalize_name(row["last_name"])

        tags = {
            part.strip().lower()
            for part in re.split(r"[;,]", row["tags"])
            if part.strip()
        }

        opted_out = row["opted_out"].strip().lower() in {"y", "yes", "true", "1"}
        source = row["source"].strip().lower()

        prepared.append({
            "index": index,
            "first_name": first_name,
            "last_name": last_name,
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": source,
            "tags": tags,
            "opted_out": opted_out,
            "updated_dt": updated,
        })

    # Union-find makes matching transitive, including chains of email/phone matches.
    parents = list(range(len(prepared)))

    def find(i):
        while parents[i] != i:
            parents[i] = parents[parents[i]]
            i = parents[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parents[rb] = ra

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(prepared):
        if row["email"]:
            if row["email"] in email_owner:
                union(i, email_owner[row["email"]])
            else:
                email_owner[row["email"]] = i

        last_name_key = row["last_name"].casefold()
        if row["phone"] and last_name_key:
            key = (row["phone"], last_name_key)
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, row in enumerate(prepared):
        groups.setdefault(find(i), []).append(row)

    def choose(group, field, require_valid=False):
        candidates = [
            row for row in group
            if row[field] and (not require_valid or row[field])
        ]
        if not candidates:
            return ""
        chosen = min(
            candidates,
            key=lambda row: (
                row["source"] != "manual",
                -row["updated_dt"].timestamp(),
                row["index"],
            ),
        )
        return chosen[field]

    output = []
    for group in groups.values():
        group.sort(key=lambda row: row["index"])
        latest = max(row["updated_dt"] for row in group)

        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email", require_valid=True),
            "phone": choose(group, "phone", require_valid=True),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(set().union(*(row["tags"] for row in group)))),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
            "_earliest_index": group[0]["index"],
        })

    output.sort(key=lambda item: item.pop("_earliest_index"))
    return output
